import { db, storage, json, error, increment } from '@appdeploy/sdk';
import { createHash, randomBytes, randomUUID } from 'node:crypto';

type Kind = 'service' | 'business';
type Status = 'pending' | 'approved' | 'hidden';
type Entry = {
  id: string; kind: Kind; title: string; category: string; description: string;
  commune: string; coverage: string[]; phone: string; email: string;
  ownerEmailHash: string; showPhone: boolean; showEmail: boolean; photos: string[];
  ownerHash: string; status: Status; createdAt: string;
  reviewCount: number; ratingTotal: number; approvedAt?: string;
};
type Review = { id: string; entryId: string; emailHash: string; rating: number;
  status: 'pending' | 'approved'; createdAt: string };
type Report = { id: string; entryId: string; emailHash: string; reason: string;
  status: 'pending' | 'resolved'; createdAt: string };
const TABLE = 'tc_local_directory_v1';
const REVIEWS = 'tc_local_reviews_v1';
const REPORTS = 'tc_local_reports_v1';
const COMMUNES = [
  'Angol', 'Collipulli', 'Ercilla', 'Lumaco', 'Los Sauces', 'Purén',
  'Renaico', 'Traiguén', 'Victoria', 'Mulchén', 'Negrete', 'Nacimiento',
];
const sha = (value: string) => createHash('sha256').update(value).digest('hex');
const text = (value: unknown, max: number) =>
  String(value ?? '').trim().replace(/[<>]/g, '').slice(0, max);
const emailValid = (value: string) => /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value);
const phoneValid = (value: string) => /^\+?[0-9()\s-]{8,20}$/.test(value) && value.replace(/\D/g, '').length >= 8;
function localCommune(value: unknown): string | null {
  const normalized = text(value, 100).normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();
  if (normalized === 'mininco' || normalized === 'villa mininco') return 'Collipulli';
  if (normalized === 'coihue' || normalized === 'coigue') return 'Negrete';
  if (normalized === 'capitan pastene') return 'Lumaco';
  return COMMUNES.find(place =>
    place.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase() === normalized) ?? null;
}
async function getEntry(id: string) {
  if (!/^local_[a-f0-9-]{36}$/.test(id)) return null;
  const [entry] = await db.get<Entry>(TABLE, [id], { consistent: true });
  return entry ? { ...entry, id } : null;
}
export async function listLocalDirectory(query: Record<string, string>) {
  const place = query.place === 'Todas' ? null : localCommune(query.place || 'Angol');
  if (!place && query.place !== 'Todas') return error('La comuna no pertenece al territorio.', 400);
  const kind: Kind | null = query.kind === 'all' ? null : query.kind === 'business' ? 'business' : 'service';
  // The public index may span several DB pages. Filter across bounded pages,
  // rather than treating only the first 120 records as the entire directory.
  const matching:Entry[]=[];
  const search=text(query.search,90).toLocaleLowerCase('es-CL');
  let nextToken:string|undefined=query.cursor||undefined;
  if(nextToken&&(nextToken.length>1800||/[<>\r\n]/.test(nextToken)))return error('Cursor inválido.',400);
  const seen=new Set<string>();
  for(let page=0;page<8;page++){
    const batch=await db.list<Entry>(TABLE,{limit:24,...(nextToken?{nextToken}:{})});
    matching.push(...batch.items.filter(e=>e.status==='approved'&&(!kind||e.kind===kind)&&
      (!place||e.commune===place||(e.coverage||[]).includes(place))&&
      (!search||[e.title,e.category,e.description].some(v=>v.toLocaleLowerCase('es-CL').includes(search)))));
    const next=batch.nextToken;if(!next){nextToken=undefined;break;}
    if(seen.has(next))return error('Error de paginación.',503);
    seen.add(next);nextToken=next;if(matching.length>=24)break;
  }
  const paths = matching.flatMap(item => item.photos).slice(0, 120);
  const urls = paths.length ? await storage.url(paths) : [];
  const map = new Map(urls.map(item => [item.path, item.url]));
  return json({
    items: matching.map(item => ({
      id: item.id, kind: item.kind, title: item.title, category: item.category,
      description: item.description, commune: item.commune, coverage: item.coverage,
      photos: item.photos.map(path => map.get(path)).filter(Boolean),
      createdAt: item.createdAt, contactAvailable: item.showPhone || item.showEmail,
      reviewCount: item.reviewCount,
      rating: item.reviewCount >= 3
        ? Math.round((item.ratingTotal / item.reviewCount) * 10) / 10 : null,
      reviewsAreVerified: false,
    })),
    partial: Boolean(nextToken), nextCursor:nextToken||null,
  });
}
export async function publicLocalDirectoryEntry(id:string){
 const e=await getEntry(id);if(!e||e.status!=='approved')return error('Ficha no disponible.',404);
 return json({entry:{id:e.id,kind:e.kind,title:e.title,category:e.category,description:e.description,commune:e.commune,
 coverage:e.coverage,photos:[],reviewCount:e.reviewCount,rating:e.reviewCount>=3?Math.round(e.ratingTotal/e.reviewCount*10)/10:null,
 contactAvailable:e.showPhone||e.showEmail}});
}
export async function myLocalDirectoryEntries(email:string){
 const owner=text(email,120).toLowerCase();if(!emailValid(owner))return error('Confirma tu correo.',401);
 const matches:Entry[]=[];const seen=new Set<string>();let token:string|undefined;
 for(let page=0;page<100;page++){
  const batch=await db.list<Entry>(TABLE,{limit:100,...(token?{nextToken:token}:{})});
  matches.push(...batch.items.filter(e=>e.ownerEmailHash===sha(owner)));
  token=batch.nextToken;if(!token)break;if(seen.has(token))return error('Consulta incompleta.',503);seen.add(token);
 }
 if(token)return error('Consulta incompleta.',503);
 return json({items:matches.map(e=>({id:e.id,kind:e.kind,title:e.title,commune:e.commune,status:e.status,
 category:e.category,description:e.description,photosCount:e.photos.length}))});
}
export async function removeLocalDirectoryByEmail(id:string,email:string){
 const e=await getEntry(id),owner=text(email,120).toLowerCase();
 if(!e||e.status==='hidden'||!emailValid(owner)||e.ownerEmailHash!==sha(owner))return error('No autorizado.',403);
 const [ok]=await db.tx.update(TABLE,[{id,record:{status:'hidden',phone:'',email:'',ownerEmailHash:'',ownerHash:'',showPhone:false,showEmail:false,photos:[],description:'',removedAt:new Date().toISOString()}}],{patch:true});
 if(!ok)return error('No se pudo retirar.',503);
 if(e.photos.length)await storage.delete(e.photos);
 return json({removed:true});
}
export async function createLocalDirectory(body: unknown) {
  const input = (body ?? {}) as Record<string, unknown>;
  const kind = input.kind === 'service' || input.kind === 'business' ? input.kind : null;
  const commune = localCommune(input.commune);
  const title = text(input.title, 90);
  const category = text(input.category, 60);
  const description = text(input.description, 750);
  const phone = text(input.phone, 24);
  const email = text(input.email, 120).toLowerCase();
  if (!kind || !commune || title.length < 3 || !category || description.length < 15)
    return error('Completa el oficio o negocio, la comuna y la descripción.', 400);
  if (!emailValid(email) || !phoneValid(phone))
    return error('Debes informar un correo y teléfono de contacto válidos.', 400);
  if (input.consent !== true || (input.showEmail !== true && input.showPhone !== true))
    return error('Autoriza la publicación y al menos una vía de contacto.', 400);
  const images = Array.isArray(input.photos) ? input.photos : [];
  if (images.length > 3) return error('Se admiten hasta tres fotografías.', 400);
  const encodedImages: string[] = [];
  for (const original of images) {
    if (typeof original !== 'string' || original.length > 310000 || !/^[A-Za-z0-9+/]+=*$/.test(original))
      return error('La fotografía tiene un formato o tamaño inválido.', 400);
    let bytes: string;
    try { bytes = atob(original); }
    catch { return error('El archivo de imagen no se pudo decodificar.', 400); }
    if (bytes.length < 300 || bytes.length > 225000 ||
        bytes.charCodeAt(0) !== 0xff || bytes.charCodeAt(1) !== 0xd8 || bytes.charCodeAt(2) !== 0xff ||
        bytes.includes('Exif\u0000\u0000') || bytes.includes('http://ns.adobe.com/xap/'))
      return error('Solo se aceptan JPEG optimizados sin EXIF.', 400);
    encodedImages.push(original);
  }
  const id = 'local_' + randomUUID();
  const ownerToken = randomBytes(24).toString('hex');
  const paths = encodedImages.map((_, index) => 'local-directory/' + id + '/' + index + '.jpg');
  if (paths.length) {
    const result = await storage.write(paths.map((path, index) => ({
      path, content: encodedImages[index], contentType: 'image/jpeg',
    })));
    if (result.length !== paths.length || result.some(ok => !ok))
      return error('No se pudieron guardar las imágenes.', 503);
  }
  const entry: Entry = {
    id, kind, title, category, description, commune, coverage: [commune],
    phone, email, ownerEmailHash: sha(email), showPhone: input.showPhone === true,
    showEmail: input.showEmail === true, photos: paths, ownerHash: sha(ownerToken),
    status: 'pending', createdAt: new Date().toISOString(),
    reviewCount: 0, ratingTotal: 0,
  };
  try {
    const [saved] = await db.tx.add(TABLE, [entry]);
    if (!saved) return error('No se pudo confirmar el envío.', 503);
    return json({ received: true, pendingModeration: true, id, ownerToken }, 202);
  } catch (cause) {
    console.warn('LOCAL_DIRECTORY_UNCERTAIN ' + String(cause).slice(0, 140));
    return error('No se confirmó el registro. Solicita revisión antes de repetir el envío.', 503);
  }
}
export async function localDirectoryContact(id: string) {
  const entry = await getEntry(id);
  if (!entry || entry.status !== 'approved') return error('Publicación no disponible.', 404);
  if (!entry.showPhone && !entry.showEmail) return error('El contacto no está autorizado.', 404);
  return json({ phone: entry.showPhone ? entry.phone : null,
    email: entry.showEmail ? entry.email : null });
}
// Owner-only receipt; it never leaks phone, email, photos, or someone else's listing.
// It is safe for an anonymous visitor ONLY with the random one-time owner token.
export async function localDirectoryStatus(id: string, body: unknown) {
  const entry = await getEntry(id);
  const token = text((body as Record<string, unknown> | null)?.ownerToken, 80);
  if (!entry || !token || sha(token) !== entry.ownerHash)
    return error('Comprobante no disponible.', 404);
  // Owner-only preview for pending/approved listings. Signed links are never
  // returned from the public directory until moderation approves the entry.
  const signed = entry.photos.length
    ? await storage.url(entry.photos.slice(0,3)).catch(() => []) : [];
  return json({
    id: entry.id, status: entry.status, title: entry.title,
    category: entry.category, description: entry.description,
    commune: entry.commune, kind: entry.kind, photosCount: entry.photos.length,
    previewPhotos: signed.map(image=>image.url).filter(Boolean),
    createdAt: entry.createdAt,
  });
}

export async function localDirectoryRemove(id: string, body: unknown) {
  const entry = await getEntry(id);
  const token = text((body as Record<string, unknown> | null)?.ownerToken, 80);
  if (!entry || entry.status==='hidden' || !token || sha(token) !== entry.ownerHash) return error('Sin autorización.', 403);
  const [ok] = await db.tx.update(TABLE, [{
    id, record: {status:'hidden',phone:'',email:'',ownerEmailHash:'',ownerHash:'',showPhone:false,showEmail:false,photos:[],description:'',removedAt:new Date().toISOString()},
  }], { patch: true });
  if (!ok) return error('No fue posible retirar la publicación.', 503);
  if (entry.photos.length) await storage.delete(entry.photos);
  return json({ removed: true });
}
export async function submitLocalReview(id: string, body: unknown, verifiedEmail: string) {
  const entry = await getEntry(id);
  const input = (body ?? {}) as Record<string, unknown>;
  // Email comes only from requireAuth() on the server; ignore email in request.
  const email = text(verifiedEmail, 120).toLowerCase();
  const rating = Number(input.rating);
  if (!entry || entry.status !== 'approved')
    return error('Publicación no disponible.', 404);
  if (!emailValid(email) || !Number.isInteger(rating) || rating < 1 || rating > 5 || input.hired !== true)
    return error('Confirma tu correo, selecciona las estrellas y declara haber contratado o comprado.', 400);
  const digest = sha(email);
  if (digest === entry.ownerEmailHash) return error('No puedes evaluar tu propio servicio.', 400);
  const reviewId = 'review_' + sha(id + ':' + digest);
  const review: Review = {
    id: reviewId, entryId: id, emailHash: digest, rating,
    status: 'pending', createdAt: new Date().toISOString(),
  };
  const [ok] = await db.tx.add(REVIEWS, [review]);
  if (!ok) return error('Este contacto ya evaluó el servicio.', 409);
  return json({ received: true, pendingModeration: true, verifiedHire: false }, 202);
}
export async function reportLocalDirectory(id: string, body: unknown) {
  const entry = await getEntry(id);
  const input = (body ?? {}) as Record<string, unknown>;
  const email = text(input.email, 120).toLowerCase();
  const reason = text(input.reason, 80);
  if (!entry || entry.status !== 'approved' || !emailValid(email) ||
      !['Información incorrecta', 'Posible estafa', 'Imágenes no autorizadas', 'Otro'].includes(reason))
    return error('Denuncia inválida.', 400);
  const report: Report = {
    id: 'report_' + randomUUID(), entryId: id, emailHash: sha(email), reason,
    status: 'pending', createdAt: new Date().toISOString(),
  };
  const [ok] = await db.tx.add(REPORTS, [report]);
  return ok ? json({ received: true }, 202) : error('No se pudo registrar la denuncia.', 503);
}
export async function adminLocalQueue() {
  // A pending listing must not disappear from moderation because it fell
  // outside the first page. Read all bounded pages of each review queue.
  async function queue<T>(table: string) {
    const items: T[] = [];
    let nextToken: string | undefined;
    for (let pass = 0; pass < 6; pass++) {
      const batch = await db.list<T>(table, {
        limit: 200, ...(nextToken ? { nextToken } : {}),
      });
      items.push(...batch.items);
      nextToken = batch.nextToken;
      if (!nextToken) break;
    }
    return { items, nextToken };
  }
  const [entries, reviews, reports] = await Promise.all([
    queue<Entry>(TABLE), queue<Review>(REVIEWS), queue<Report>(REPORTS),
  ]);
  return json({
    entries: entries.items.filter(item => item.status === 'pending'),
    reviews: reviews.items.filter(item => item.status === 'pending'),
    reports: reports.items.filter(item => item.status === 'pending'),
    partial: Boolean(entries.nextToken || reviews.nextToken || reports.nextToken),
  });
}
export async function adminLocalDecision(id: string, status: 'approved' | 'hidden') {
  const entry = await getEntry(id);
  if (!entry || entry.status !== 'pending') return error('Ficha no pendiente.', 409);
  const [ok] = await db.tx.update(TABLE, [{
    id, record: { status, approvedAt: status === 'approved' ? new Date().toISOString() : null },
    if: { status: 'pending' },
  }], { patch: true });
  return ok ? json({ status }) : error('Estado no confirmado.', 409);
}
export async function adminApproveLocalReview(id: string) {
  if (!/^review_[a-f0-9]{64}$/.test(id)) return error('Evaluación inválida.', 400);
  const [review] = await db.get<Review>(REVIEWS, [id], { consistent: true });
  if (!review || review.status !== 'pending') return error('Evaluación no pendiente.', 409);
  const entry = await getEntry(review.entryId);
  if (!entry || entry.status !== 'approved') return error('Servicio no disponible.', 409);
  await db.transact([
    db.tx.update(REVIEWS, [{ id, record: { status: 'approved' }, if: { status: 'pending' } }], { patch: true }),
    db.tx.update(TABLE, [{
      id: review.entryId,
      record: { reviewCount: increment(1), ratingTotal: increment(review.rating) },
    }], { patch: true }),
  ]);
  return json({ approved: true });
}
export async function adminResolveLocalReport(id: string) {
  if (!/^report_[a-f0-9-]{36}$/.test(id)) return error('Denuncia inválida.', 400);
  const [ok] = await db.tx.update(REPORTS, [{ id, record: { status: 'resolved' } }], { patch: true });
  return ok ? json({ resolved: true }) : error('Denuncia no encontrada.', 404);
}

import { db } from '@appdeploy/sdk';
import { hydrateSocialFindings } from './social-evidence-store';

type Stored = Record<string, unknown>;
const SOCIAL_HOSTS = new Set(['facebook.com','www.facebook.com','m.facebook.com','instagram.com','www.instagram.com']);
const PAGE_SIZE = 3;
const FINDINGS_PER_RUN = 20;

function text(value:unknown, length=1000) {
  return typeof value === 'string' ? value.slice(0, length) : '';
}

function sourceUrl(value:unknown, media=false) {
  if (typeof value !== 'string' || value.length > 4000) return null;
  try {
    const url = new URL(value);
    if (url.protocol !== 'https:' || url.username || url.password || url.port) return null;
    if ([...url.searchParams.keys()].some(key => /^(access_token|api_key|apikey|token)$/i.test(key))) return null;
    if (media ? !/\.(fbcdn\.net|cdninstagram\.com)$/.test(url.hostname) : !SOCIAL_HOSTS.has(url.hostname)) return null;
    return url.toString();
  } catch { return null; }
}

function count(value:unknown) {
  if (value === null || value === undefined || value === '') return null;
  const number = Number(value);
  return Number.isSafeInteger(number) && number >= 0 ? number : null;
}

function finding(value:unknown) {
  const row = value && typeof value === 'object' && !Array.isArray(value) ? value as Stored : {};
  return {
    postUrl:sourceUrl(row.postUrl), postDate:text(row.postDate, 100) || null,
    mediaUrl:sourceUrl(row.mediaUrl, true), medium:text(row.medium, 30),
    title:text(row.title, 300), company:text(row.company, 300), commune:text(row.commune, 300),
    contact:text(row.contact, 600), deadline:text(row.deadline, 150),
    requirements:text(row.requirements, 1000), text:text(row.text, 6000),
    textTruncated:row.textTruncated===true || text(row.text,10000).length>6000,
    textOriginalLength:count(row.textOriginalLength),
    transcriptionAvailable:typeof row.transcriptionAvailable==='boolean' ? row.transcriptionAvailable : null,
  };
}

// Reads only evidence already captured by the existing workers. Never invokes a provider or writes.
export async function readLocalSourceEvidence(cursor?:string) {
  if (cursor && (cursor.length > 4096 || /[\r\n]/.test(cursor))) throw new Error('Invalid local evidence cursor');
  const rows = await db.list<Stored>('social_capture_runs', { limit:PAGE_SIZE, ...(cursor ? { nextToken:cursor } : {}) });
  const references=rows.items.flatMap(row=>(Array.isArray(row.findings)?row.findings:[]).slice(0,FINDINGS_PER_RUN)) as Stored[];
  const full=await hydrateSocialFindings(references);
  let at=0;
  const items = rows.items.map(row => {
    const all = Array.isArray(row.findings) ? row.findings : [];
    return {
      id:row.id, sourceKey:text(row.sourceKey, 100), sourceName:text(row.sourceName, 300),
      sourceUrl:sourceUrl(row.sourceUrl), territory:text(row.territory, 300), status:text(row.status, 80),
      capturedAt:text(row.createdAt, 100) || null, processedAt:text(row.processedAt, 100) || null,
      posts:count(row.posts), postCursor:count(row.postCursor), mediaCursor:count(row.mediaCursor),
      images:count(row.images), imagesRead:count(row.imagesRead), jobNotices:count(row.jobNotices),
      textPostsRead:count(row.textPostsRead), findingsKnown:Array.isArray(row.findings),
      findingsTotal:Array.isArray(row.findings) ? all.length : null,
      findingsTruncated:all.length > FINDINGS_PER_RUN, findings:full.slice(at,at+=Math.min(all.length,FINDINGS_PER_RUN)).map(finding),
    };
  });
  return {
    schema:'trabajo-cerca.existing-local-evidence.v1', readOnly:true, providerCalls:0,
    coverage:'one_bounded_page_of_existing_captures', pageSize:PAGE_SIZE,
    nextCursor:rows.nextToken ?? null, hasMore:Boolean(rows.nextToken), items,
    stats:{ runsReturned:items.length, findingsReturned:items.reduce((sum,row) => sum + row.findings.length, 0) },
    checkedAt:new Date().toISOString(),
  };
}

import { db } from '@appdeploy/sdk';
import { createHash } from 'node:crypto';
import { importReview, decideReview } from './radar-review-inbox';
import { enqueueAdminReviewedOffer } from './radar-review-queue';

// Auxiliary B: independently classifies its own queue; never marks an offer verified
// and never writes to the public catalog.
type BOffer = { id:string; url?:string; status?:string; title?:string; company?:string|null; commune?:string|null; publishedAt?:string|null; application?:string|null; reason?:string };
const completed = new Set(['closed','not_job','duplicate']);
export async function triageMotorBQueue() {
  const [checkpoint] = await db.get<{cursor?:string}>('motor_b_aux_state',['current'],{consistent:true});
  const page = await db.list<BOffer>('motor_b_offers',{limit:8,...(checkpoint?.cursor?{nextToken:checkpoint.cursor}:{})});
  let examined=0,ready=0,needsEvidence=0,bridged=0,bridgeRejected=0,submitted=0;
  for(const candidate of page.items) {
    if(completed.has(candidate.status||''))continue;
    const hasIdentity=Boolean(candidate.url&&candidate.title&&candidate.commune);
    const hasEvidence=Boolean(candidate.company&&candidate.publishedAt&&candidate.application);
    const classification=hasIdentity&&hasEvidence?'ready_for_primary_verifier':'needs_source_evidence';
    const reason=classification==='needs_source_evidence'
      ?[!candidate.title?'title':null,!candidate.commune?'workplace':null,!candidate.company?'employer':null,!candidate.publishedAt?'original_date':null,!candidate.application?'application':null].filter(Boolean).join(',')
      :'eligible_for_primary_verification_not_published';
    const id=candidate.id;
    if(!id)continue;
    const [old]=await db.get<{classification?:string;reason?:string}>('motor_b_aux_queue',[id],{consistent:true});
    if(!old){
      await db.tx.add('motor_b_aux_queue',[{id,sourceOfferId:id,classification,reason,checkedAt:new Date().toISOString()}]);
    }else if(old.classification!==classification||old.reason!==reason) {
      await db.tx.update('motor_b_aux_queue',[{id,record:{classification,reason,checkedAt:new Date().toISOString()}}],{patch:true});
    }
    examined++;if(hasIdentity&&hasEvidence)ready++;else needsEvidence++;
    if(hasIdentity&&candidate.url&&candidate.title&&candidate.commune){
      const candidate_key=createHash('sha256').update('motor-b|'+candidate.url+'|'+candidate.title).digest('hex').slice(0,22);
      const item={candidate_key,url:candidate.url,source_id:'motor-b-independent',status:'revision_obligatoria',reported_territories:[candidate.commune],published_date_evidence:candidate.publishedAt||null,deadline_evidence:null};
      try{const result=await importReview({items:[item]});bridged+=result.inserted;bridgeRejected+=result.rejected;
        if(hasEvidence&&candidate.status==='ready'){
          const reviewId='tc_'+candidate_key;
          try{
            await decideReview({id:reviewId,status:'ready_for_final_check'});
            const outcome=await enqueueAdminReviewedOffer({id:reviewId});
            if(outcome.queued)submitted++;
          }catch(e){console.warn('MOTOR_B_PRIMARY_REVIEW_PENDING '+String(e).slice(0,160));}
        }
      }
      catch(e){bridgeRejected++;console.warn('MOTOR_B_BRIDGE_REVIEW '+String(e).slice(0,150));}
    }
  }
  if(checkpoint)await db.tx.update('motor_b_aux_state',[{id:'current',record:{cursor:page.nextToken||null,updatedAt:new Date().toISOString()}}],{patch:true});
  else await db.tx.add('motor_b_aux_state',[{id:'current',cursor:page.nextToken||null,updatedAt:new Date().toISOString()}]);
  console.warn('MOTOR_B_AUX '+JSON.stringify({examined,ready,needsEvidence,bridged,bridgeRejected,submitted,hasMore:!!page.nextToken}));
  return {examined,ready,needsEvidence};
}

import {createHash} from 'node:crypto';
import * as pdfjsWorker from 'pdfjs-dist/legacy/build/pdf.worker.mjs';
(globalThis as any).pdfjsWorker = pdfjsWorker;
export type BDocument={kind:'pdf'|'image';url:string;sha256:string;text:string;method:string;status:'extracted'|'needs_ocr'|'failed';reason?:string};
const sha=(bytes:Uint8Array)=>createHash('sha256').update(bytes).digest('hex');
export async function extractBDocument(url:string,bytes:Uint8Array,mime:string):Promise<BDocument>{
 const kind=mime.includes('pdf')||/\.pdf(?:\?|$)/i.test(url)?'pdf':'image';
 const base={kind,url,sha256:sha(bytes)} as const;
 if(kind==='pdf'){
  try{
